    bufferOffset += 4;
    *(uint32_t*)(outputBuffer + bufferOffset) = val->queueFamilyIndex;
    bufferOffset += 4;
    *(uint32_t*)(outputBuffer + bufferOffset) = val->queueCount;
    bufferOffset += 4;

    if (val->pQueuePriorities) {
        int arrSize = val->queueCount ? val->queueCount : 0;
        *(int*)(outputBuffer + bufferOffset) = arrSize;
        bufferOffset += 4;
        memcpy(outputBuffer + bufferOffset, val->pQueuePriorities, arrSize * 4);
        bufferOffset += arrSize * 4;
    }
    else {
        *(int*)(outputBuffer + bufferOffset) = 0;
        bufferOffset += 4;
    }
