    val->queueFamilyIndex = VT_DECODE_VALUE(cursor, bufferOffset, uint32_t);
    if (!vt_decode_advance(cursor, &bufferOffset, (size_t)(4))) return false;
    val->queueCount = VT_DECODE_VALUE(cursor, bufferOffset, uint32_t);
    if (!vt_decode_validate_count(cursor, (uint64_t)val->queueCount)) return false;
    if (!vt_decode_advance(cursor, &bufferOffset, (size_t)(4))) return false;

