    val->viewMask = VT_DECODE_VALUE(cursor, bufferOffset, uint32_t);
    if (!vt_decode_advance(cursor, &bufferOffset, (size_t)(4))) return false;
    val->colorAttachmentCount = VT_DECODE_VALUE(cursor, bufferOffset, uint32_t);
    if (!vt_decode_validate_count(cursor, (uint64_t)val->colorAttachmentCount)) return false;
    if (!vt_decode_advance(cursor, &bufferOffset, (size_t)(4))) return false;

    int32_t dataSize8 = 0;
    if (!vt_decode_data_size_at(cursor, bufferOffset, &dataSize8)) return false;
    if ((uint64_t)val->colorAttachmentCount != (uint64_t)dataSize8) return vt_decode_fail(cursor, VT_DECODE_ERROR_ARGUMENT);
