static inline int vt_sizeof_VkComputePipelineCreateInfo(VkComputePipelineCreateInfo* val) {
    int bufferSize = 0;
    bufferSize += 4; // sType
    void* pNext = val->pNext;
    while (pNext) {
        bufferSize += 4;
        VkBaseOutStructure* sBase = pNext;
        void* oldPNext = sBase->pNext;
        sBase->pNext = NULL;

        switch (sBase->sType) {
            case VK_STRUCTURE_TYPE_PIPELINE_CREATION_FEEDBACK_CREATE_INFO: {
                bufferSize += 4;
                bufferSize += vt_sizeof_VkPipelineCreationFeedbackCreateInfo((VkPipelineCreationFeedbackCreateInfo*)pNext);
                break;
            }
            default: {
                bufferSize += 4;
                break;
            }
        }

        sBase->pNext = oldPNext;
        pNext = sBase->pNext;
    }
    bufferSize += 4;
    bufferSize += 4; // flags
    bufferSize += vt_sizeof_VkPipelineShaderStageCreateInfo(&val->stage);
    bufferSize += vt_sizeof_VkPipelineLayout(val->layout);
    bufferSize += vt_sizeof_VkPipeline(val->basePipelineHandle);
    bufferSize += 4; // basePipelineIndex
    return bufferSize;
}

